Each instrument can be checked independently because a hold depends only on the immediately preceding symbol and sound state of the same instrument. A barline resets that state under the current rule.

```python
def invalid_holds(bars):
    """Return (bar, pulse) positions of invalid holds, numbered from 1.

    bars must be a list of bars. Each bar may be a four-character string
    or a list of four one-character symbols: X, –, and ~.
    Raise ValueError for malformed bars or unsupported symbols.
    """
    if not isinstance(bars, list):
        raise ValueError("bars must be a list")

    for bar_number, bar in enumerate(bars, start=1):
        if not isinstance(bar, (str, list)) or len(bar) != 4:
            raise ValueError(f"bar {bar_number} must contain four symbols")
        for pulse, symbol in enumerate(bar, start=1):
            if not isinstance(symbol, str) or symbol not in ("X", "–", "~"):
                raise ValueError(
                    f"unsupported symbol at bar {bar_number}, pulse {pulse}"
                )

    invalid = []
    for bar_number, bar in enumerate(bars, start=1):
        sounding = False  # A hold cannot cross a barline.
        for pulse, symbol in enumerate(bar, start=1):
            if symbol == "X":
                sounding = True
            elif symbol == "–":
                sounding = False
            elif not sounding:
                invalid.append((bar_number, pulse))
                # An invalid hold cannot authorize the next hold.

    return invalid
```

Focused tests using only Python’s standard library:

```python
import unittest


class WorksheetCheckerTests(unittest.TestCase):
    def test_hold_at_start_and_following_invalid_hold(self):
        self.assertEqual(invalid_holds(["~~X–"]), [(1, 1), (1, 2)])

    def test_hold_after_rest(self):
        self.assertEqual(invalid_holds(["X–~–"]), [(1, 3)])

    def test_hold_across_barline_and_following_invalid_hold(self):
        self.assertEqual(invalid_holds(["–––X", "~~X–"]), [(2, 1), (2, 2)])

    def test_valid_internal_chains(self):
        self.assertEqual(invalid_holds(["X~~–", "XX~~"]), [])

    def test_malformed_bar_length(self):
        with self.assertRaises(ValueError):
            invalid_holds(["X~–"])

    def test_unsupported_symbol(self):
        with self.assertRaises(ValueError):
            invalid_holds(["X-~–"])  # ASCII hyphen is not the rest symbol.


if __name__ == "__main__":
    unittest.main()
```

The rest symbol is the en dash `–`, as specified. An empty list is accepted as a row with no bars.
